from mesh_config import compile_route_profile

def test_service_execution():
    base = {"prefix": "/api", "timeout_ms": 500}
    env = {"timeout_ms": 250}
    prof = compile_route_profile("mesh-1", base, env)
    assert prof["mesh_id"] == "mesh-1"
    assert prof["prefix"] == "/api"
    assert prof["rules"]["timeout_ms"] == 250

def test_header_extraction():
    base = {
        "prefix": "/api",
        "matchers": {
            "X-Tenant-Id": {"type": "header"},
            "Authorization": {"type": "header"},
            "X-Trace-Id": {"type": "header"}
        }
    }
    env = {
        "matchers": {
            "X-Tenant-Id": {"type": "header"},
            "Authorization": {"type": "header"},
            "X-Trace-Id": {"type": "header"}
        }
    }
    prof = compile_route_profile("mesh-1", base, env)
    expected_headers = ["X-Tenant-Id", "Authorization", "X-Trace-Id"]
    assert prof["headers"] == expected_headers
